example_schema_snippet:
{
  "type": "object",
  "properties": {
    "destination": {
      "type": "string",
      "partial_validation": "prefix",
      "streamable": true,
      "repair_hint": "accept common abbreviations (NYC -> New York City)"
    },
    "attachments": {
      "type": "array",
      "items": {
        "type": "object"
      },
      "streamable": true
    }
  },
  "required": ["destination"]
}
